/** A movement's classifications: the three a person decides, then the dispositions the product sets. */
export const CLASSIFICATIONS = [
  "BUSINESS",
  "PERSONAL",
  "MIXED",
  "NOT_YET_PROCESSED",
  "PROCESSED_UNCLASSIFIED",
  "SKIPPED_BY_RULE",
  "FAILED_VALIDATION",
  "REVIEWED_EXCLUDED",
] as const;
export type Classification = (typeof CLASSIFICATIONS)[number];
export const isClassification = (id: string): id is Classification =>
  (CLASSIFICATIONS as readonly string[]).includes(id);

/** Which way a movement's money went. */
export const DIRECTIONS = [
  "INCOMING",
  "OUTGOING",
  "INTERNAL_TRANSFER",
] as const;
export type Direction = (typeof DIRECTIONS)[number];
export const isDirection = (id: string): id is Direction =>
  (DIRECTIONS as readonly string[]).includes(id);

